def dist2(x, y):  # 유클리드 거리 제곱
    return sum((a - b) ** 2 for a, b in zip(x, y))

def triplet_loss(f, anchor, pos, neg, alpha=0.2):
    a, p, n = f(anchor), f(pos), f(neg)  # 정규화 임베딩
    # 동일인 거리 + 마진이 타인 거리보다 작아야 0
    return max(0.0, dist2(a, p) - dist2(a, n) + alpha)

def same_person(f, img1, img2, threshold):
    return dist2(f(img1), f(img2)) < threshold

factory-method-pattern.pseudocode:
class Creator:
    def factory_method(self):  # 서브클래스가 구현
        raise NotImplementedError

    def operation(self):
        # 생성할 구체 클래스를 모른 채 제품 사용
        product = self.factory_method()
        return product.deliver()

class TruckCreator(Creator):
    def factory_method(self):
        return Truck()

class ShipCreator(Creator):
    def factory_method(self):
        return Ship()

# 새 운송 수단 추가 = 서브클래스 추가 (OCP)
for creator in [TruckCreator(), ShipCreator()]:
    creator.operation()
